#[cfg(test)]
mod w334_tests {
    use super::*;
    use crate::domain::ModelRef;
    use serde_json::json;

    fn reference(config: &AppConfig) -> Vec<ModelRef> {
        let mut models=Vec::new();
        if let Ok(model)=config.active_model_config() {
            models.push(ModelRef::new(model.provider,model.model));
        }
        for profile in config.providers.values() {
            let model=profile.to_model_config().unwrap();
            let pair=ModelRef::new(model.provider,model.model);
            if !models.contains(&pair) {models.push(pair);}
        }
        models
    }

    #[tokio::test(flavor = "current_thread")]
    async fn w334_configured_pairs_keep_exact_first_order() {
        let codex_path=Path::new(env!("CARGO_MANIFEST_DIR")).join("../../configs/codex.config.toml");
        let codex=AppConfig::load(Some(&codex_path)).await.expect("checked-in profile");
        let active=codex.active_model_config().expect("checked-in active model");
        assert_eq!((active.provider.as_str(),active.model.as_str()),("opencode","deepseek-v4.1-flash"));
        assert_eq!(active.reasoning.effort.as_deref(),Some("high"));

        let profile=|provider:&str,model:&str| json!({
            "provider":provider,"model":model,
            "reasoning":{"effort":"synthetic-effort"}
        });
        let mut profiles=serde_json::Map::new();
        profiles.insert("a".into(),profile("A","same"));
        profiles.insert("b".into(),profile("B","same"));
        profiles.insert("c".into(),profile("A","same"));
        profiles.insert("z".into(),profile("C","last"));
        profiles.insert(" z ".into(),profile("D","space-key"));
        profiles.insert(" ".into(),profile("E","blank-key"));
        for i in 0..128 {
            profiles.insert(format!("p-{i:03}"),profile(if i%3==0 {"B"} else {"A"},"same"));
        }

        let empty:AppConfig=serde_json::from_value(json!({})).unwrap();
        let synthetic=|active:Option<&str>|serde_json::from_value::<AppConfig>(json!({
            "providers":profiles,"active_provider":active,
        })).unwrap();
        let cases=[("codex",codex),("empty",empty),
                   ("active",synthetic(Some("z"))),("space",synthetic(Some(" z "))),
                   ("missing",synthetic(Some("missing"))),("blank",synthetic(Some(" "))),
                   ("inactive",synthetic(None))];
        for (name,config) in cases {
            let expect=reference(&config);
            let (got,m)=crate::w334_alloc::measure(||configured_model_options(&config));
            assert_eq!(got,expect);
            match name {
                "codex" => {assert_eq!(got[0],ModelRef::new("opencode","deepseek-v4.1-flash"));},
                "active" => {assert_eq!(got[0],ModelRef::new("C","last"));},
                "space" => {assert_eq!(got[0],ModelRef::new("D","space-key"));},
                "missing" | "blank" | "inactive" => {assert_eq!(got[0],ModelRef::new("E","blank-key"));},
                "empty" => {assert!(got.is_empty());},
                _=>unreachable!(),
            }
            if let Some(dir)=std::env::var_os("W334_WITNESS_DIR") {
                std::fs::write(std::path::PathBuf::from(dir).join(format!("{name}.json")),serde_json::to_vec(&got).unwrap()).unwrap();
            }
            eprintln!("W334 {name} {} {} {} {}",config.providers.len(),got.len(),m.calls,m.bytes);
        }
    }
}
